// readLoop parses the control-mode stream (a port of _reader_loop).
func (c *ControlClient) readLoop() {
	defer close(c.readerDone)
	br := bufio.NewReaderSize(c.r, 64<<10)
	var (
		capturing bool
		capID     string
		deliver   bool
		body      []string
	)
	for {
		line, err := readControlLine(br, c.cfg.maxLine)
		if err != nil {
			if errors.Is(err, io.EOF) {
				c.teardown(ExitInfo{Kind: ExitEOF})
			} else {
				c.teardown(ExitInfo{Kind: ExitTransport, Err: err})
			}
			return
		}
		if capturing {
			if m := controlHeadRE.FindStringSubmatch(line); m != nil && m[1] != "begin" && m[2] == capID {
				capturing = false
				if deliver {
					rc := 0
					if m[1] == "error" {
						rc = 1
					}
					out := strings.Join(body, "\n")
					if len(body) > 0 {
						out += "\n"
					}
					c.resolveNext(controlReply{rc: rc, out: out})
				}
				// A server-emitted block (the attach acknowledgement): dropped.
				body = nil
				continue
			}
			body = append(body, line)
			continue
		}
		if m := controlHeadRE.FindStringSubmatch(line); m != nil && m[1] == "begin" {
			flags, _ := strconv.ParseUint(m[3], 10, 64)
			capturing, capID, deliver, body = true, m[2], flags&1 != 0, nil
			continue
		}
		if controlExitRE.MatchString(line) {
			reason := strings.TrimSpace(strings.TrimPrefix(line, "%exit"))
			c.teardown(ExitInfo{Kind: ExitTmux, Reason: reason})
			return
		}
		// Any other line outside a block is an asynchronous notification
		// (%session-changed, %window-renamed, …): discarded.
	}
}

// readControlLine returns the next line without its trailing "\n". A final
// line with no "\n" is a truncated stream and reports io.EOF.
func readControlLine(br *bufio.Reader, maxLine int) (string, error) {
	var acc []byte
	for {
		frag, err := br.ReadSlice('\n')
		if len(acc)+len(frag) > maxLine+1 { // +1: the "\n" itself
			return "", errLineTooLong
		}
		acc = append(acc, frag...)
		switch {
		case err == nil:
			return string(acc[:len(acc)-1]), nil
		case errors.Is(err, bufio.ErrBufferFull):
			continue
		default:
			return "", err
		}
	}
}

// resolveNext hands a reply to the oldest pending request. A reply with
// nothing pending is spurious and dropped.
func (c *ControlClient) resolveNext(res controlReply) {
	c.mu.Lock()
	if len(c.pending) == 0 {
		c.mu.Unlock()
		return
	}
	job := c.pending[0]
	c.pending[0] = nil
	c.pending = c.pending[1:]
	c.mu.Unlock()
	job.result <- res
}

// teardown runs once: it records why the client died, answers every pending
// request with -1 (including one whose reply was mid-capture), closes Done,
// closes both pipe ends (unblocking a blocked Write or Read) and, for a
// process-owning client, arms the close watchdog. It takes no lock that a
// blocked writer could hold.
func (c *ControlClient) teardown(info ExitInfo) {
	c.once.Do(func() {
		c.mu.Lock()
		c.dead = true
		c.exit = info
		pend := c.pending
		c.pending = nil
		c.mu.Unlock()
		for _, job := range pend {
			job.result <- controlReply{rc: -1}
		}
		close(c.done)
		c.w.Close() // tmux drops a control client on stdin EOF
		c.r.Close()
		if c.waitDone != nil {
			go c.watchdog()
		}
	})
}

// watchdog kills the child if it has not exited closeTimeout after teardown.
func (c *ControlClient) watchdog() {
	timer := time.NewTimer(c.cfg.closeTimeout)
	defer timer.Stop()
	select {
	case <-c.waitDone:
	case <-timer.C:
		c.cancelProc()
	}
}
